import {utilityTrendReport} from './utility-trends.js?v=adult-learning-1';
import {NAV_LAYERS} from './navigation-map.js?v=adult-learning-1';
import {educationReport} from './education.js?v=adult-learning-1';
import {breakdownCharts} from './report-breakdowns.js?v=adult-learning-1';
import {METRICS,historyWindow,metricSeries} from './reports.js?v=adult-learning-1';
export function showReports({city,dialog,close,setLayer,setNavigationLayer,review}){const c=city(),$=s=>document.querySelector(s),fmt=n=>Number.isFinite(n)?n.toLocaleString('en-US',{maximumFractionDigits:1}):'Not recorded',date=m=>new Date(Date.UTC(c.startYear+Math.floor(m/12),m%12,1)).toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'});
 dialog('City data · maps & trends',`${utilityTrendReport(c)}${breakdownCharts(c)}${educationReport(c)}<button id="reportFeedback">Give utilities milestone feedback</button><p>Compare up to three trends on a shared timeline. Each graph has its own labeled scale. Monthly records cover the most recent 100 years; new metrics in older saves begin recording from your next month.</p><label>Time window<select id="reportYears"><option value="1">1 year</option><option value="10" selected>10 years</option><option value="100">100 years</option></select></label><div class="actions">${[0,1,2].map((n)=>`<label>Trend ${n+1}<select id="reportMetric${n}">${n?'<option value="">None</option>':''}${Object.entries(METRICS).map(([k,v])=>`<option value="${k}" ${k===['population','funds','aura'][n]?'selected':''}>${v[0]}</option>`).join('')}</select></label>`).join('')}</div><div id="reportGraphs"></div><h3>Data maps</h3><p>Show a layer in the city view, or use it in the navigation map while keeping your current city view and construction tool.</p><div class="table-scroll"><table><thead><tr><th>Map</th><th>City view</th><th>Navigation map</th></tr></thead><tbody>${Object.entries({tunnels:'Tunnels',...Object.fromEntries(Object.entries(NAV_LAYERS).filter(([key])=>key!=='city'))}).map(([key,name])=>`<tr><td>${name}</td><td><button data-report-layer="${key}" aria-label="Show ${name} in city view">Show in city</button></td><td>${Object.hasOwn(NAV_LAYERS,key)?`<button data-report-navigation="${key}" aria-label="Use ${name} as navigation map">Use as map</button>`:'—'}</td></tr>`).join('')}</tbody></table></div><p class="fine">Job capacity series show available positions. Commerce and Industry employment count filled jobs reached by road or transit; unemployment is the share of the workforce without a reachable job. Water pollution averages all map tiles; air pollution and land value average zoned tiles. Aura averages residents’ happiness. Education by age uses the modeled age cohorts. Annual electricity and garbage totals use recorded months only; missing history is not inferred.</p>`);
 function render(){const rows=historyWindow(c,Number($('#reportYears').value)),keys=[...new Set([0,1,2].map(i=>$('#reportMetric'+i).value).filter(Boolean))];if(!rows.length){$('#reportGraphs').innerHTML='<p>No monthly records yet. Run the city to start collecting data.</p>';return;}
 const lo=rows[0].month,hi=rows.at(-1).month,colors=['#c4ed89','#8ddce8','#ffc483'];
 $('#reportGraphs').innerHTML=keys.map((key,i)=>{const {values,min,max}=metricSeries(rows,key),[label,unit]=METRICS[key];if(!values.length)return `<h3>${label}</h3><p>Not recorded in this period.</p>`;const floor=Math.min(0,min),ceiling=unit==='%'?100:Math.max(floor+1,max),x=m=>60+(m-lo)/Math.max(1,hi-lo)*490,y=v=>135-(v-floor)/(ceiling-floor)*95;let path='',last=null;for(const p of values){path+=`${last!==null&&p.month===last+1?'L':'M'}${x(p.month).toFixed(2)},${y(p.value).toFixed(2)} `;last=p.month;}return `<h3>${label} <small>(${unit})</small></h3><svg viewBox="0 0 580 175" role="img" aria-label="${label} from ${date(lo)} to ${date(hi)}"><path d="M60 35V135H550" fill="none" stroke="#78979a"/><text x="55" y="42" text-anchor="end" fill="#b0c9ce" font-size="10">${fmt(ceiling)}</text><text x="55" y="138" text-anchor="end" fill="#b0c9ce" font-size="10">${fmt(floor)}</text><path d="${path}" fill="none" stroke="${colors[i]}" stroke-width="2"/>${values.length===1?`<circle cx="${x(values[0].month)}" cy="${y(values[0].value)}" r="3" fill="${colors[i]}"/>`:''}<text x="60" y="163" fill="#b0c9ce" font-size="11">${date(lo)}</text><text x="550" y="163" text-anchor="end" fill="#b0c9ce" font-size="11">${date(hi)}</text></svg><p>Latest recorded: ${fmt(values.at(-1).value)} · ${date(values.at(-1).month)}. Range: ${fmt(min)}–${fmt(max)}.</p>`;}).join('')+`<details><summary>View exact monthly values (${rows.length} records)</summary><div class="table-scroll" style="max-height:320px;overflow:auto"><table><thead><tr><th>Month</th>${keys.map(k=>`<th>${METRICS[k][0]}</th>`).join('')}</tr></thead><tbody>${rows.slice().reverse().map(h=>`<tr><td>${date(h.month)}</td>${keys.map(k=>`<td>${fmt(h[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;
 }
 for(const [id,keys] of [['reportPowerTrends',['powerDemand','powerAvailable','powerUnserved']],['reportWaterTrends',['waterDemand','waterAvailable','waterUnserved']],['reportUtilityUsage',['powerUsagePercent','waterUsagePercent','']]])$('#'+id).onclick=()=>{keys.forEach((key,i)=>$('#reportMetric'+i).value=key);render();$('#reportGraphs').scrollIntoView({block:'start'});};
 $('#reportFeedback').onclick=()=>review(2);
 document.querySelectorAll('[data-report-navigation]').forEach(b=>b.onclick=()=>{setNavigationLayer(b.dataset.reportNavigation);close();});$('#reportYears').onchange=render;for(let i=0;i<3;i++)$('#reportMetric'+i).onchange=render;document.querySelectorAll('[data-report-layer]').forEach(b=>b.onclick=()=>{setLayer(b.dataset.reportLayer);close();});render();
}
